<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Stockroom · Inventory</title>
  <style>
    :root{font-family:Arial,Helvetica,sans-serif;color:#17231c;background:#f3f7f2}*{box-sizing:border-box}body{margin:0}.top{background:#fff;border-bottom:1px solid #e2e9e1;padding:18px max(24px,calc((100% - 1080px)/2));display:flex;align-items:center;justify-content:space-between}.brand{font-size:19px;font-weight:700;color:#216c38}.wrap{max-width:1080px;margin:38px auto;padding:0 24px}.intro{display:flex;justify-content:space-between;align-items:end;margin-bottom:22px}.intro h1{margin:0;font-size:28px}.muted{color:#718074}.panel{background:white;border:1px solid #e2e9e1;border-radius:14px;padding:22px;box-shadow:0 8px 24px #18351d0a}.auth{max-width:420px;margin:70px auto}.formrow{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:18px 0}label{display:block;font-size:13px;color:#556259}input{width:100%;margin-top:6px;padding:11px;border:1px solid #d7e0d6;border-radius:8px;font-size:14px}button{border:0;border-radius:8px;background:#287a46;color:white;padding:11px 15px;font-weight:600;cursor:pointer}button.secondary{background:#edf4ed;color:#285839}button.danger{background:#fff0ed;color:#9b392a}button:disabled{opacity:.6}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{text-align:left;border-bottom:1px solid #edf0ed;padding:12px 9px;font-size:14px}th{font-size:12px;color:#718074;text-transform:uppercase}.actions{display:flex;gap:8px}.toolbar{display:flex;justify-content:space-between;align-items:center}.notice{min-height:20px;color:#a23b2b;font-size:14px}.hidden{display:none!important}@media(max-width:680px){.formrow{grid-template-columns:1fr}.table-wrap{overflow-x:auto}.intro{align-items:start;gap:10px;flex-direction:column}}
  </style>
</head>
<body>
  <header class="top"><div class="brand">▰ Stockroom</div><button id="signout" class="secondary hidden">Sign out</button></header>
  <main class="wrap">
    <section id="auth" class="panel auth"><h1 id="auth-title">Welcome to Stockroom</h1><p id="auth-subtitle" class="muted">Sign in to manage your inventory.</p><form id="login"><label id="name-wrap" class="hidden">Your name<input name="name" autocomplete="name"></label><label style="margin-top:12px">Email<input name="email" type="email" required autocomplete="email"></label><label style="display:block;margin-top:12px">Password<input name="password" type="password" required minlength="8" autocomplete="current-password"></label><p id="auth-error" class="notice"></p><button id="auth-submit">Sign in</button> <button id="auth-toggle" class="secondary" type="button">Create account</button></form></section>
    <section id="inventory" class="hidden">
      <div class="intro"><div><p class="muted" style="margin:0 0 8px">INVENTORY OVERVIEW</p><h1>Your products</h1></div><button id="refresh" class="secondary">Refresh</button></div>
      <div class="panel"><div class="toolbar"><div><strong id="count">0 products</strong><div class="muted" style="font-size:13px;margin-top:4px">Add stock items and keep an eye on quantities.</div></div></div>
        <form id="add-product"><div class="formrow"><label>Product name<input name="name" required maxlength="120"></label><label>Product code<input name="sku" required maxlength="80"></label><label>Category<input name="category" maxlength="80" value="Uncategorized"></label><label>Quantity<input name="quantity" type="number" min="0" required value="0"></label><label>Unit cost (₱)<input name="price" type="number" min="0" step="0.01" required value="0"></label><label>Reorder level<input name="reorder_level" type="number" min="0" required value="5"></label></div><button>Add product</button></form><p id="message" class="notice"></p>
        <div class="table-wrap"><table><thead><tr><th>Product</th><th>Code</th><th>Category</th><th>Quantity</th><th>Unit cost</th><th></th></tr></thead><tbody id="rows"></tbody></table></div>
      </div>
    </section>
  </main>
  <script>
    const tokenKey='stockroom_token', auth=document.querySelector('#auth'), inventory=document.querySelector('#inventory');
    let token=localStorage.getItem(tokenKey);
    function state(){auth.classList.toggle('hidden',!!token);inventory.classList.toggle('hidden',!token);document.querySelector('#signout').classList.toggle('hidden',!token);if(token)load()}
    async function request(path,options={}){const r=await fetch('/api'+path,{...options,headers:{Accept:'application/json','Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})}});const d=await r.json();if(!r.ok)throw Error(d.message||'Request failed');return d}
    async function load(){try{const list=await request('/products');document.querySelector('#count').textContent=`${list.length} product${list.length===1?'':'s'}`;document.querySelector('#rows').innerHTML=list.map(p=>`<tr><td>${escapeHtml(p.name)}</td><td>${escapeHtml(p.sku)}</td><td>${escapeHtml(p.category)}</td><td>${p.quantity}</td><td>₱${Number(p.price).toFixed(2)}</td><td><button class="danger" data-delete="${p.id}">Delete</button></td></tr>`).join('');}catch(e){document.querySelector('#message').textContent=e.message}}
    function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
    let registering=false;document.querySelector('#auth-toggle').onclick=()=>{registering=!registering;document.querySelector('#name-wrap').classList.toggle('hidden',!registering);document.querySelector('#name-wrap input').required=registering;document.querySelector('#auth-title').textContent=registering?'Create your account':'Welcome to Stockroom';document.querySelector('#auth-subtitle').textContent=registering?'Start organizing your inventory.':'Sign in to manage your inventory.';document.querySelector('#auth-submit').textContent=registering?'Create account':'Sign in';document.querySelector('#auth-toggle').textContent=registering?'Back to sign in':'Create account'};
    document.querySelector('#login').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const d=await request(registering?'/register':'/login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});token=d.token;localStorage.setItem(tokenKey,token);state()}catch(x){document.querySelector('#auth-error').textContent=x.message}});
    document.querySelector('#add-product').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget), d=Object.fromEntries(f);for(const k of ['quantity','reorder_level'])d[k]=Number(d[k]);d.price=Number(d.price);try{await request('/products',{method:'POST',body:JSON.stringify(d)});e.currentTarget.reset();document.querySelector('#message').textContent='Product added.';load()}catch(x){document.querySelector('#message').textContent=x.message}});
    document.querySelector('#rows').addEventListener('click',async e=>{const id=e.target.dataset.delete;if(!id)return;try{await request(`/products/${id}`,{method:'DELETE'});load()}catch(x){document.querySelector('#message').textContent=x.message}});
    document.querySelector('#refresh').onclick=load;document.querySelector('#signout').onclick=()=>{localStorage.removeItem(tokenKey);token=null;document.querySelector('#rows').replaceChildren();state()};state();
  </script>
</body></html>
